// 1. Ambil payload dari Webhook (Sesuai spesifikasi terbaru)
const raw = $input.first().json;
const payload = raw.body || raw;

// 2. Ekstrak Variabel
const assetCode = payload.asset_code || '-';
const assetName = payload.asset_name || '-';
const category = payload.category || '-';
const location = payload.location || '-';
const ipAddress = payload.ip_address || '-';
const type = (payload.type || 'offline').toLowerCase();
const severity = (payload.severity || 'critical').toUpperCase();

// 3. Logika Cooldown 10 Menit (Anti-Spam)
const staticData = $getWorkflowStaticData('global');
const COOLDOWN_MS = 10 * 60 * 1000; 
const now = Date.now();
const lastSent = staticData[`last_sent_${assetCode}`] || 0;

if (now - lastSent < COOLDOWN_MS) {
  return []; // Hentikan eksekusi (mencegah spam)
}
staticData[`last_sent_${assetCode}`] = now;

// 4. Format Waktu (Timestamp -> WIB)
let timeFormatted = payload.timestamp || '-';
if (timeFormatted !== '-') {
  try {
    timeFormatted = new Date(timeFormatted).toLocaleString('id-ID', {
      timeZone: 'Asia/Jakarta', dateStyle: 'medium', timeStyle: 'short'
    }) + ' WIB';
  } catch (e) {}
}

// 5. Ekstrak Symptoms (Jika ada)
let symptomText = "Tidak ada data gejala spesifik.";
if (payload.symptoms) {
  if (typeof payload.symptoms === 'object') {
    const ping = payload.symptoms.ping_latency ? `Latensi ${payload.symptoms.ping_latency}` : '';
    const loss = payload.symptoms.packet_loss ? `Packet Loss ${payload.symptoms.packet_loss}` : '';
    symptomText = [ping, loss].filter(Boolean).join(' | ') || JSON.stringify(payload.symptoms);
  } else {
    symptomText = payload.symptoms;
  }
}

// 6. Knowledge Base (SOP Wafian untuk perangkat spesifik)
const sopDatabase = {
  "SRV-01": "Server Utama. Cek iDRAC/IPMI, sensor hardware, RAM, dan disk.",
  "CCTV-01": "CCTV Gerbang. Cek kabel UTP luar, port PoE, dan lampu infra merah.",
  "RPI-01": "Edge Gateway HO. Cek service 'taims-monitoring', koneksi LAN, dan microSD.",
  "SWM-01": "Switch Utama. Cek kabel trunking, modul PoE overheat, atau loop broadcast."
};
const sopSpesifik = sopDatabase[assetCode] || "Lakukan pengecekan kabel jaringan dan status daya perangkat.";

// 7. Susun Prompt AI (Sesuai Aturan Format Wafian)
let promptAI = "";
let emoji = "🔴";
let headerFallback = "ALERT";

if (type === 'warning') {
  emoji = "🟡";
  headerFallback = "WARNING: POTENSI GANGGUAN";
  promptAI = `Kamu adalah AI Network Analyst untuk T-AIMS.
Perangkat: ${assetName} (${assetCode})
Lokasi: ${location} | IP: ${ipAddress}
Status: WARNING (Early Warning)
Gejala: ${symptomText}
SOP Acuan: ${sopSpesifik}

Tugasmu: Berikan analisis prediktif dan tindakan pencegahan.
Gunakan format WAJIB ini (teks biasa, bukan JSON):
🟡 [T-AIMS WARNING] POTENSI GANGGUAN TERDETEKSI
━━━━━━━━━━━━━━━━━━━━
📌 Aset: ${assetName} (${assetCode})
🏢 Lokasi: ${location} | 🌐 IP: ${ipAddress}
⚠️ Severity: WARNING (Early Warning)
📊 Gejala: ${symptomText}

🔍 Analisis Prediktif AI (Gemini):
[Jelaskan potensi penyebab sebelum alat mati total]

🛠️ Tindakan Pencegahan Teknisi:
[1 langkah preventif sebelum down total]
━━━━━━━━━━━━━━━━━━━━
Bot: @taims_alert_arik_bot • n8n Early Warning Engine`;

} else {
  emoji = "🔴";
  headerFallback = "OFFLINE ALERT";
  promptAI = `Kamu adalah AI Network Analyst untuk T-AIMS.
Perangkat: ${assetName} (${assetCode})
Lokasi: ${location} | IP: ${ipAddress}
Status: CRITICAL (Offline)
SOP Acuan: ${sopSpesifik}

Tugasmu: Berikan analisis root cause dan SOP penanganan.
Gunakan format WAJIB ini (teks biasa, bukan JSON):
🔴 [T-AIMS ALERT] PERANGKAT DOWN / OFFLINE
━━━━━━━━━━━━━━━━━━━━
📌 Aset: ${assetName} (${assetCode})
🏢 Lokasi: ${location} | 🌐 IP: ${ipAddress}
⚠️ Severity: CRITICAL | SLA MTTR: < 30 Menit

🔍 Analisis Root Cause & Dampak:
[Jelaskan akar masalah teknis & dampak operasional kantor]

🛠️ SOP Penanganan Teknisi:
1. Verifikasi: [Langkah remote/ping]
2. Fisik: [Langkah cek kabel/PoE/LED]
3. Solusi: [Tindakan eskalasi/recovery]
━━━━━━━━━━━━━━━━━━━━
Bot: @taims_alert_arik_bot • n8n Incident Engine`;
}

// 8. Pesan Fallback (Jika AI Timeout / Graceful Degradation)
const messageFallback = `${emoji} [T-AIMS ${headerFallback}]
━━━━━━━━━━━━━━━━━━━━
📌 Aset: ${assetName} (${assetCode})
🏢 Lokasi: ${location} | 🌐 IP: ${ipAddress}
⚠️ Severity: ${severity}
⏰ Waktu: ${timeFormatted}

ℹ️ Notifikasi Standar (AI sedang limit/down)
━━━━━━━━━━━━━━━━━━━━
Bot: @taims_alert_arik_bot • n8n Engine`;

// 9. Return Data untuk Node HTTP Request (Gemini)
return {
  json: {
    prompt_ai: promptAI,
    message: messageFallback,
    asset_code: assetCode,
    type: type
  }
};
